"use client";

import { forwardRef, type HTMLAttributes } from "react";
import { Button as AriaButton } from "react-aria-components";
import { alertDefaults, type AlertSpecProps } from "../generated/alert.types";
import { cx } from "../utils/cx";
import { CloseIcon, ErrorIcon, InfoIcon, SuccessIcon, WarningIcon } from "../utils/icons";

export interface AlertProps
  extends AlertSpecProps,
    Omit<HTMLAttributes<HTMLDivElement>, keyof AlertSpecProps | "className" | "title" | "role"> {
  className?: string;
}

const tones: Record<NonNullable<AlertSpecProps["variant"]>, { box: string; icon: string; Icon: typeof InfoIcon; say: string }> = {
  info: {
    box: "bg-[var(--rd-color-feedback-info-subtle)] border-s-[var(--rd-color-feedback-info)]",
    icon: "text-[var(--rd-color-feedback-info)]",
    Icon: InfoIcon,
    say: "Information",
  },
  success: {
    box: "bg-[var(--rd-color-feedback-success-subtle)] border-s-[var(--rd-color-feedback-success)]",
    icon: "text-[var(--rd-color-feedback-success)]",
    Icon: SuccessIcon,
    say: "Success",
  },
  warning: {
    box: "bg-[var(--rd-color-feedback-warning-subtle)] border-s-[var(--rd-color-feedback-warning)]",
    icon: "text-[var(--rd-color-feedback-warning)]",
    Icon: WarningIcon,
    say: "Warning",
  },
  danger: {
    box: "bg-[var(--rd-color-feedback-danger-subtle)] border-s-[var(--rd-color-feedback-danger)]",
    icon: "text-[var(--rd-color-feedback-danger)]",
    Icon: ErrorIcon,
    say: "Error",
  },
};

export const Alert = forwardRef<HTMLDivElement, AlertProps>(function Alert(
  {
    children,
    title,
    variant = alertDefaults.variant,
    onDismiss,
    dismissLabel = alertDefaults.dismissLabel,
    className,
    ...rest
  },
  ref,
) {
  const tone = tones[variant];
  const { Icon } = tone;
  // Warnings and errors interrupt a screen reader; the rest wait for a pause.
  const urgent = variant === "warning" || variant === "danger";
  return (
    <div
      {...rest}
      ref={ref}
      role={urgent ? "alert" : "status"}
      className={cx(
        "flex items-start gap-3 rounded-[var(--rd-radius-overlay)] border border-s-4 border-[var(--rd-color-border-default)] p-3 " +
          "text-sm text-[var(--rd-color-text-default)]",
        tone.box,
        className,
      )}
    >
      <Icon className={cx("mt-0.5 size-5 shrink-0", tone.icon)} />
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        {/* Said in words, so the tone isn't only a color and an icon. */}
        <span className="sr-only">{tone.say}: </span>
        {title && <p className="font-medium">{title}</p>}
        <div>{children}</div>
      </div>
      {onDismiss && (
        <AriaButton
          aria-label={dismissLabel}
          onPress={onDismiss}
          className={
            "-m-1 flex size-7 shrink-0 items-center justify-center rounded-[var(--rd-radius-control)] outline-none " +
            "data-[hovered]:bg-[var(--rd-color-surface-default)]/60 " +
            "data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]"
          }
        >
          <CloseIcon className="size-4" />
        </AriaButton>
      )}
    </div>
  );
});

// Generated by rdloom codegen from specs/alert.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const alertVariantValues = ["info", "success", "warning", "danger"] as const;

/** An inline message about the state of the page or a task: a tip, a success, a warning or an error. For brief confirmations that disappear, use Toast. */
export interface AlertSpecProps {
  /**
   * The message. Say what happened and what to do next.
   */
  children: ReactNode;
  /**
   * Optional bold first line, e.g. 'Payment failed'.
   */
  title?: string;
  /**
   * Tone and urgency. Warning and danger interrupt a screen reader; info and success wait their turn.
   * @default "info"
   */
  variant?: "info" | "success" | "warning" | "danger";
  /**
   * When set, a close button appears and calls this. You remove the alert.
   */
  onDismiss?: () => void;
  /**
   * Accessible name of the close button.
   * @default "Dismiss"
   */
  dismissLabel?: string;
}

export const alertDefaults = {
  variant: "info",
  dismissLabel: "Dismiss",
} as const;

export const alertMeta = {
  "name": "Alert",
  "version": "0.1.0",
  "status": "experimental",
  "role": "alert"
} as const;
